package br.com.sagio.config;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public Map<String,Object> validation(MethodArgumentNotValidException ex){List<Map<String,String>> errors=ex.getBindingResult().getFieldErrors().stream().map(e->Map.of("campo",e.getField(),"mensagem",Objects.requireNonNullElse(e.getDefaultMessage(),"Valor inválido"))).toList();return Map.of("erro","Dados inválidos","detalhes",errors);} @ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) public Map<String,String> generic(Exception ex){return Map.of("erro","Erro interno. Tente novamente mais tarde.");} }